"""本地业务页面交互。"""

def detail_fragment(item):
    return "<input id=\"address\" list=\"areas\"><datalist id=\"areas\"><option value=\"桐花苑 1 栋\"><option value=\"桐花苑 2 栋\"></datalist><button id=\"address-check\">查询上门范围</button><output id=\"address-result\"></output><output id=\"provider\"></output><script>let address=document.querySelector('#address');let service=document.querySelector('#address-result');let time=document.querySelector('#result');address.oninput=()=>{service.textContent='';time.textContent='';document.querySelector('#provider').textContent=''};document.querySelector('#address-check').onclick=()=>{let a=address.value;if(a==='桐花苑 1 栋'){service.textContent='桐花苑 1 栋：服务区';document.querySelector('#provider').textContent='城区维修队'}else if(a==='桐花苑 2 栋'){service.textContent='桐花苑 2 栋：限制预约';document.querySelector('#provider').textContent='东区维修队'}else service.textContent='地址未确认'};document.querySelector('#preview').onclick=()=>time.textContent=service.textContent.includes('服务区')?'周二上门':'暂不可确认';</script>"

def source_extension(item):
    return """<label>可选时段<select id="visit-slot"><option value="">先核对地址</option></select></label><label><input id="terms-confirmed" type="checkbox">已核对上门条款</label><output id="terms"></output><output id="qualification-preview"></output><script>(()=>{
let slot=document.querySelector('#visit-slot'),terms=document.querySelector('#terms'),address=document.querySelector('#address'),confirmed=document.querySelector('#terms-confirmed'),preview=document.querySelector('#qualification-preview');
let checkedAddress='';address.addEventListener('input',()=>{slot.innerHTML='<option value="">先核对地址</option>';terms.textContent='';checkedAddress='';confirmed.checked=false;preview.textContent='';});
document.querySelector('#address-check').addEventListener('click',()=>{let selected=address.value;terms.textContent='条款读取中';slot.innerHTML='<option value="">等待时段</option>';confirmed.checked=false;preview.textContent='';setTimeout(()=>{if(address.value!==selected)return;checkedAddress=selected;terms.textContent=selected==='桐花苑 1 栋'?'城区维修队：需确认上门条款':selected==='桐花苑 2 栋'?'东区维修队：范围待核':'地址未确认';slot.innerHTML=selected==='桐花苑 1 栋'?'<option value="tue">周二</option>':'<option value="">暂无可确认时段</option>';},65)});
document.querySelector('#preview').addEventListener('click',()=>{preview.textContent=checkedAddress===address.value && slot.value && confirmed.checked?checkedAddress+' / '+terms.textContent+' / '+slot.options[slot.selectedIndex].text:'资格未确认';});
})();</script>"""
